-- 4. Timeline
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (0, '2022', 'أساسيات ما قبل السريرية', 'Preclinical foundations', 'سنتان من الأساسات: تشريح الرأس والعنق، الأنسجة، مواد طب الأسنان، وفن قراءة الأشعة — البنية التي يقف عليها كل شيء بعدها.', 'Two years of fundamentals: head and neck anatomy, histology, dental materials, and the art of reading radiographs — the structure everything else stands on.', '["تشريح الرأس والعنق","مواد طب الأسنان","قراءة الأشعة"]'::jsonb, '["Head & neck anatomy","Dental materials","Radiographic interpretation"]'::jsonb, '[]'::jsonb, true);
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (1, '2023', 'مختبر المحاكاة', 'Simulation lab', 'أول تحضير وحشو على أنماط التدريب (التايبودونت): قاعات دراسية كاملة، ومبرد لأول مرة بين يديّ — تحت إشراف دقيق خطوة بخطوة.', 'First preps and fillings on typodonts: full simulation wards, a handpiece in my hands for the first time — under close step-by-step supervision.', '["التحضير المحافظ","الحشوات المركبة","الطباعة والتشخيص"]'::jsonb, '["Conservative preparation","Composite restorations","Impressions & diagnosis"]'::jsonb, '[{"labelAr":"تمرين مختبري","labelEn":"lab exercise","value":85,"suffixAr":"","suffixEn":""}]'::jsonb, true);
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (2, '2024', 'أول مرضى حقيقيين', 'First real patients', 'بداية التدريب السريري: فحص وتشخيص، تنظيف ومنع، وحشوات بسيطة. أهم درس؟ اليد الجيدة تبدأ من جلسة إنصات جيدة.', 'Clinical rotations begin: exams and diagnosis, prophylaxis, simple restorations. The biggest lesson? A good hand starts with a good listening session.', '["الفحص الشامل","التنظيف والوقاية","التخدير الموضعي"]'::jsonb, '["Comprehensive exam","Prophylaxis","Local anesthesia"]'::jsonb, '[{"labelAr":"حشوة","labelEn":"fillings","value":45,"suffixAr":"","suffixEn":""},{"labelAr":"جلسة لثة","labelEn":"perio visits","value":25,"suffixAr":"","suffixEn":""}]'::jsonb, true);
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (3, '2025', 'التوسع السريري', 'Clinical expansion', 'سنوات التخصص الدقيق تبدأ: علاج جذور بالأدوات الدوارة، ترميمات أكبر، وبداية التعويضات الثابتة — مع أول حالات أمامية تجميلية.', 'Specialty rotations begin: rotary endodontics, larger restorations, and the first fixed prosthesis cases — plus my first anterior esthetic cases.', '["علاج الجذور الدوّار","الترميمات الأمامية","تحضير التيجان"]'::jsonb, '["Rotary endodontics","Anterior restorations","Crown preparation"]'::jsonb, '[{"labelAr":"حشوة","labelEn":"fillings","value":38,"suffixAr":"","suffixEn":""},{"labelAr":"علاج جذور","labelEn":"endo cases","value":12,"suffixAr":"","suffixEn":""},{"labelAr":"تاج","labelEn":"crowns","value":6,"suffixAr":"","suffixEn":""}]'::jsonb, true);
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (4, '2026', 'سنة الحصيلة', 'The tally so far', 'منتصف السنة الخامسة — هذه حصيلة ما أنجزته تحت الإشراف حتى الآن في عيادات الكلية، وأرقامها تنمو كل أسبوع.', 'Mid fifth year — here''s what I''ve completed under supervision in the faculty clinics so far, and the numbers grow every week.', '["إدارة موعد كامل","توثيق الحالات","تثقيف المريض"]'::jsonb, '["Full appointment workflow","Case documentation","Patient education"]'::jsonb, '[{"labelAr":"حشوة مكتملة","labelEn":"completed fillings","value":120,"suffixAr":"+","suffixEn":"+"},{"labelAr":"علاج جذور","labelEn":"endo treatments","value":45,"suffixAr":"+","suffixEn":"+"},{"labelAr":"جلسة معالجة لثة","labelEn":"perio sessions","value":60,"suffixAr":"+","suffixEn":"+"},{"labelAr":"عمل تعويضي","labelEn":"prosthetic works","value":15,"suffixAr":"+","suffixEn":"+"}]'::jsonb, true);
INSERT INTO timeline_entries (sort_order, year, title_ar, title_en, description_ar, description_en, skills_ar, skills_en, stats, published)
VALUES (5, '2027', 'سنة التخرج', 'Graduation year', 'التدريب الخارجي، مشروع التخرج، ثم اليميد ثم التخرج في يونيو 2027 بإذن الله — وبعده مباشرة: برامج التدريب المتقدم.', 'Externship, the graduation project, then the oath and graduation in June 2027 — and right after: advanced training programs.', '["التدريب الخارجي","مشروع التخرج","الامتحان النهائي"]'::jsonb, '["Externship","Graduation project","Final boards"]'::jsonb, '[]'::jsonb, true);

-- 5. Case Studies
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('anterior-composite', 0, 'fillings', 'ترميم سن أمامي مكسور بالحشوة المركبة', 'Restoring a fractured front tooth with composite', 'كسر في الثلث الحادي للسن الجانبي بعد حادث منزلي — ترميم طبقي بلونين في جلسة واحدة.', 'A fracture in the lateral incisor''s incisal third after a household accident — layered two-shade restoration in a single visit.', '2026-03', true, '/images/case-1-before.webp', '/images/case-1-after.webp', 'مقارنة قبل وبعد لترميم سن أمامي مكسور', 'Before and after comparison of a fractured front tooth restoration', '{"complaintAr":"شاب في العشرينيات يأتي بعد ساعة من كسر زاوية السن الجانبي العلوي أثناء فتح زجاجة — لا ألم، لكن الخجل من الابتسامة واضح.","complaintEn":"A man in his twenties arrives an hour after breaking the corner of his upper lateral incisor while opening a bottle — no pain, but clearly embarrassed to smile.","diagnosisAr":"كسر غير معقّد في الثلث القاطع بدون إصابة اللب أو النفق — الاختبارات الحسية طبيعية، والصورة الشعاعية استبعدت امتداد الكسر إلى الجذر.","diagnosisEn":"An uncomplicated fracture of the incisal third with no pulp or canal involvement — vitality tests normal, and the radiograph ruled out fracture extension to the root.","planAr":"ترميم مباشر بالحشوة المركبة بتقنية الطبقات: قاعدة معتمة (دنتين) ثم طبقة شفافة (مينا) لاصطناع انكسار الضوء الطبيعي، مع إعادة بناء الزاوية بالكامل.","planEn":"Direct composite restoration using the layering technique: an opaque dentin base, then a translucent enamel layer to mimic natural light transmission, fully rebuilding the corner.","materialsAr":"مركب نانوهجين مركب بلونين (A2 دنتين + مينا شفافة)، رابط ذاتي التخمير، وأقراص تلميع ماصة بأربعة أطوار.","materialsEn":"Two-shade nanohybrid composite (A2 dentin + translucent enamel), self-etch adhesive, and four-stage polishing discs.","learnedAr":"النجاح في الأسنان الأمامية قرار فني بقدر ما هو طبي: مطابقة اللون تحت ثلاث إضاءات مختلفة قبل البدء وفّرت عليّ إعادة العمل، وقال المريض إنه لم يعد يفرّق السن عن جيرانه.","learnedEn":"Anterior success is an artistic decision as much as a medical one: shade-matching under three different lights before starting saved me a redo — the patient said he can no longer tell the tooth from its neighbors."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('class-ii-composite', 1, 'fillings', 'حشوة خلفية مزدوجة بضرسين متجاورين', 'Class II double-surface posterior restoration', 'تسوس تحت حشوة قديمة في ضرسين متجاورين — إزالة، عزل، وترميم مزدوج بتقنية الصندوق وخطوة اللمسة السفلية.', 'Caries under an old filling in two adjacent molars — removal, isolation, and a double restoration with the box technique and proximal contact rebuild.', '2025-11', false, '/images/case-2-before.webp', '/images/case-2-after.webp', 'مقارنة قبل وبعد لحشوة ضرس خلفي', 'Before and after comparison of a posterior molar restoration', '{"complaintAr":"أم في الأربعينيات تشكو من تحسس بارد متكرر عند الطرف الخلفي الأيمن، وخيط الأسنان يتمزق عند نقطة واحدة بعينها.","complaintEn":"A woman in her forties complains of recurring cold sensitivity in the upper right back area, and floss shredding at one specific spot.","diagnosisAr":"تسوس ثانوي تحت حشوة ملغمة قديمة مع كسر جزئي في حافتها، وتسوس سطحين تقريبيين في الضرس المجاور — واضح في الأشعة البتّاوية.","diagnosisEn":"Secondary caries under an old amalgam restoration with a partially fractured margin, plus proximal caries on the neighboring molar — clear on the bitewing radiograph.","planAr":"جلسة واحدة تحت عزل بالسدّ المطاطي: إزالة الحشوة والتسوس، ثم ترميم مزدوج بشرائط فاصلة لاستعادة نقطة التلامس الطبيعية بين السنين دون فراغ طعام.","planEn":"A single rubber-dam-isolated session: removal of the old restoration and caries, then a double composite rebuild with separating matrices to restore a natural contact point without food traps.","materialsAr":"مركب خلفي قابل للتعبئة، شرائط تلامس مقوّاة، رابط شامل، وسدّ مطاطي.","materialsEn":"Packable posterior composite, reinforced contact matrices, universal adhesive, and a rubber dam.","learnedAr":"نقطة التلامس ليست تفصيلاً: فراغ بقدر رأس الدبوس يعني ضيق طعام والتهاب لثة متكرر بعد أسبوع. القياس قبل وبعد بالخيط صار عادةً عندي في كل حشوة خلفية.","learnedEn":"The contact point isn''t a detail: a gap the width of a pin head means food impaction and recurring gingivitis within a week. Measuring floss pass before and after is now a habit on every posterior restoration."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('molar-endo', 2, 'endo', 'علاج جذور ضرس العقل الأول بنظام دوّار', 'Rotary endodontic treatment of a first molar', 'لب متنخر بعد تسوس عميق — ثلاث قنوات، نظام دوّار، وحشو ثلاثي الأبعاد في جلستين.', 'A necrotic pulp after deep caries — three canals, a rotary system, and warm three-dimensional obturation in two visits.', '2026-01', false, '/images/case-3-before.webp', '/images/case-3-after.webp', 'صورة إشعاعية لعلاج جذور ضرس قبل وبعد الحشو', 'Radiograph of a molar root canal before and after obturation', '{"complaintAr":"رجل ثلاثيني يوقظ من نومه ألماً ليلياً نابضاً في ضرسه الأول السفلي الأيمن، مع شعور بأن السن «أطول من جيرانه» عند الإطباق.","complaintEn":"A man in his thirties is woken by throbbing night pain in his lower right first molar, and a feeling that the tooth is ''taller than its neighbors'' when biting.","diagnosisAr":"تسوس عميق مؤدٍ إلى تنخر اللب (التهاب لب غير رجعي/تنخري) مع حساسية إطباقية — الأشعة أظهرت آفة حول قمة الجذر.","diagnosisEn":"Deep caries leading to irreversible pulp necrosis with percussion tenderness — the radiograph showed a periapical lesion.","planAr":"علاج جذور كامل: فتح، قياس القنوات الثلاث بجهاز القياس الإلكتروني، تنظير وتوسيع بالأدوات الدوارة، مطهر بالكلورهيكسيدين، ثم حشو بالسدّ الساخن، وترميم نهائي بعدها بأسبوع.","planEn":"Full root canal treatment: access, electronic working-length measurement of all three canals, rotary shaping, chlorhexidine irrigation, warm vertical obturation, and a definitive restoration a week later.","materialsAr":"ملفات NiTi دوّارة، جهاز قياس إلكتروني، سدّ مائي بحرارة، وأوتار غير قابل للذوبان حيوياً.","materialsEn":"Rotary NiTi files, an apex locator, warm gutta-percha, and a biocompatible sealer.","learnedAr":"المريض عاد يقول: «نمت أول ليلة كاملة منذ أسابيع». علاج الجذور المشهور بألقه ليس مؤلماً بذاته؛ الألم هو تركه دون علاج. الدقة في القياس هي ما يمنع إعادة العلاج.","learnedEn":"The patient returned saying: ''I slept a full night for the first time in weeks.'' Root canals'' notorious reputation isn''t from the treatment itself — the pain is leaving it untreated. Measurement precision is what prevents retreatment."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('gingivitis-therapy', 3, 'gum', 'برنامج علاج لثة شامل لالتهاب مزمن', 'Comprehensive gum therapy program for chronic gingivitis', 'نزف لثة عند التنظيف استمر سنة — تنظيف مهني، تعديل تقنية الفرشاة، ومتابعة ثلاثية أعادت اللثة صحية في 21 يوماً.', 'A year of bleeding gums — professional cleaning, brushing technique coaching, and a three-week follow-up that restored healthy gums in 21 days.', '2025-09', false, '/images/case-4-before.webp', '/images/case-4-after.webp', 'مقارنة قبل وبعد لعلاج التهاب اللثة', 'Before and after comparison of gingivitis therapy', '{"complaintAr":"طالبة جامعية في العشرينيات: «دم في المغسل كل صباح» وتجنبت التنظيف في المواضع التي تنزف — فازداد الأمر سوءاً.","complaintEn":"A university student in her twenties: ''blood in the sink every morning'' — she avoided brushing the areas that bled, which only made it worse.","diagnosisAr":"التهاب لثة مزمن بلا جيوب عميقة أو فقد عظمي (مرحلة مبكرة قابلة للعكس تماماً) مترافق مع تراكم جير فوق اللثة وتنظيف عشوائي مرة يومياً.","diagnosisEn":"Chronic gingivitis without deep pockets or bone loss — an early, fully reversible stage — accompanied by supragingival calculus and random once-daily brushing.","planAr":"تنظيف مهني فوق وتحت اللثة في جلسة، ثم جلسة تدريب على فرشاة ناعمة وطريقة باص المعدلة 45 درجة، خيط يومي، ومواعيد متابعة في اليوم السابع والحادي والعشرين.","planEn":"Professional supragingival and subgingival cleaning in one visit, then a coaching session on a soft brush and the modified 45-degree Bass technique, daily floss, and follow-ups on day 7 and day 21.","materialsAr":"مقلع جير يدوي وموجات فوق صوتية، فرشاة ناعمة مزدوجة الشعيرات، وخيط شمعي.","materialsEn":"Hand and ultrasonic scalers, a soft dual-tufted brush, and waxed floss.","learnedAr":"أهم «أداة» في العلاج كانت دقيقة تدريب لا جهازاً: تغيير طريقة التنظيف غيّر النتيجة أكثر من التنظيف المهني نفسه. المريضة صارت تعلّم زميلاتها في السكن الطريقة الصحيحة.","learnedEn":"The most important ''instrument'' in this treatment was a coaching minute, not a device: changing the brushing method changed the outcome more than the professional cleaning itself. The patient ended up teaching her dormmates the correct technique."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('zirconia-crown', 4, 'prosth', 'تاج زيركون لضرس ضعيف بعد حشوة كبيرة', 'Zirconia crown for a weakened molar after a large filling', 'ضرس فقد أكثر من نصف بنيته بعد كسر حشوة — تحضير كامل، طبعة رقمية، وتاج زيركون أحادي اللبس.', 'A molar that lost over half its structure after a filling fracture — full preparation, a digital scan, and a monolithic zirconia crown.', '2026-05', false, '/images/case-5-before.webp', '/images/case-5-after.webp', 'مقارنة قبل وبعد لتركيب تاج زيركون', 'Before and after comparison of a zirconia crown placement', '{"complaintAr":"أب في الأربعينيات يكسر حشوته الضخمة «كل أشهر تقريباً» ويطلب حلاً نهائياً يتحمل مضغه القوي.","complaintEn":"A father in his forties breaks his large filling ''almost every month'' and asks for a definitive solution that survives his strong chewing.","diagnosisAr":"ضرس أول سفلي فقد أكثر من 50% من تاجه مع حشوات متكررة — مرشح واضح للتغطية الكاملة بدلاً من إصلاح ثالث.","diagnosisEn":"A lower first molar that lost over 50% of its crown with repeated restorations — a clear candidate for full coverage rather than a third repair.","planAr":"تحضير كامل بانحدار محسوب، طبعة بماسح فموي رقمي (بدون معاجين الطبعات المزعجة)، تاج زيركون أحادي مُصمم رقمياً، تثبيت مؤقت أسبوعاً ثم لصق نهائي.","planEn":"Full preparation with a calculated taper, a digital oral-scanner impression (no messy putty), a digitally designed monolithic zirconia crown, one week of temporary cementation, then final bonding.","materialsAr":"زيركون أحادي عالي الشفافية، ماسح رقمي، وسمنت زجاجي أيونومري لاصق.","materialsEn":"High-translucency monolithic zirconia, a digital scanner, and adhesive glass-ionomer cement.","learnedAr":"الطبعة الرقمية حوّلت أكثر خطوة يكرهها المرضى إلى مشهد «مستقبلي» يصورونه بهواتفهم. وعلمتني المتابعة أن جودة التحضير تُختبر عند اللصق: تاج يجلس دون ضغط يعني تحضيراً صحيحاً.","learnedEn":"The digital scan turned the most hated step into a ''futuristic'' moment patients film on their phones. Follow-up taught me that preparation quality is truly tested at seating: a crown that settles without pressure means the prep was right."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO case_studies (slug, sort_order, category, title_ar, title_en, summary_ar, summary_en, period, featured, image_before, image_after, image_alt_ar, image_alt_en, story, published, patient_consent)
VALUES ('smile-rehabilitation', 5, 'prosth', 'تأهيل ابتسامة بترميمات أمامية متعددة', 'Smile rehabilitation with multiple anterior restorations', 'تآكل مينا واسع بعد ارتجاع معدي — خطة مرحلية حافظة بدل تيجان كاملة: ترميمات مركبة مبنية على تصميم ابتسامة رقمي.', 'Widespread enamel erosion after acid reflux — a staged, conservative plan instead of full crowns: composite restorations built on a digital smile design.', '2026-06', false, '/images/case-6-before.webp', '/images/case-6-after.webp', 'مقارنة قبل وبعد لتأهيل ابتسامة بترميمات أمامية', 'Before and after comparison of an anterior smile rehabilitation', '{"complaintAr":"مدرّسة ثلاثينية تجنّبت الضحك أمام طلابها: أسنان أمامية «قصرت وتآكلت» وأصبح لونها باهتاً حبيباً، مع حساسية باردة مزمنة.","complaintEn":"A teacher in her thirties avoided laughing in front of her students: her front teeth ''shortened and eroded'' to a matte, opaque shade, with chronic cold sensitivity.","diagnosisAr":"تآكل حمضي معمم في الأسنان الأمامية العلوية نتيجة ارتجاع معدي غير مُدار — مع فقد طول قاطع قابل للقياس، وبدون تسوس نشط.","diagnosisEn":"Generalized acid erosion of the upper anterior teeth from unmanaged gastric reflux — with measurable loss of incisal length and no active caries.","planAr":"المرحلة صفر: إحالة لإدارة الارتجاع طبياً (بدونها سيفشل أي ترميم). ثم تصميم ابتسامة رقمي، نموذج تجريبي في الفم، وأخيراً ترميمات مركبة طبقية موزعة على جلستين — دون بَرّ زائد عن الحاجة.","planEn":"Phase zero: a medical referral to manage the reflux (any restoration fails without it). Then a digital smile design, an in-mouth mock-up, and finally layered composite restorations across two visits — with no unnecessary drilling.","materialsAr":"نظام مركب متعدد الشفافيات، قوالب سيليكون من النموذج، وورنيش فلورايد موضعي للحماية.","materialsEn":"A multi-translucency composite system, silicone indices from the mock-up, and topical fluoride varnish for protection.","learnedAr":"أحلى لحظة: دخلت المريضة للجلسة الثانية فطلبت رؤية الصورة «قبل» ثم ضحكت بصوت مسموع أول مرة. والدرس الأهم: علاج السبب قبل علاج النتيجة — وإلا أعدت الترميم كل سنة.","learnedEn":"The sweetest moment: at the second visit she asked to see the ''before'' photo, then laughed out loud for the first time. And the biggest lesson: treat the cause before the consequence — otherwise you redo the restoration every year."}'::jsonb, true, false)
ON CONFLICT (slug) DO NOTHING;

