-- 7. Research
INSERT INTO research_items (sort_order, title_ar, title_en, abstract_ar, abstract_en, link, year, published)
VALUES (0, 'عادات العناية بالفم بين طلاب الجامعات: مسح مقطعي', 'Oral Hygiene Habits Among University Students: A Cross-Sectional Survey', 'مسح شمل 412 طالباً في ثلاث كليات: فحص سريري واستبيان عن عادات التنظيف. أظهرت النتائج أن 61% لا ينظفون أسنانهم مرتين يومياً، ويتذكرون الخيط «عندما تنزف اللثة فقط» — والارتباط الأقوى كان بالمعرفة وليس بالوقت المتاح، ما يرجّح أولوية التوعية على الوعظ.', 'A survey of 412 students across three colleges: clinical screening plus a hygiene-habits questionnaire. Results showed 61% skip twice-daily brushing and remember floss ''only when gums bleed'' — the strongest correlation was with knowledge, not available time, suggesting education beats lecturing.', '/pdfs/sample-cv.pdf', '2025', true);
INSERT INTO research_items (sort_order, title_ar, title_en, abstract_ar, abstract_en, link, year, published)
VALUES (1, 'العلاقة بين أمراض اللثة والسكري من النوع الثاني: مراجعة أدبية', 'The Periodontitis–Type 2 Diabetes Link: A Literature Review', 'مراجعة لـ 38 دراسة منشورة بين 2015 و2025 حول العلاقة ثنائية الاتجاه بين التهاب اللثة المزمن والتحكم السكري، وتلخّص الأدلة على أن علاج اللثة يحسّن HbA1c بمقدار يعادل إضافة دواء — وأثرها العملي على تنسيق العناية بين طبيب الأسنان وطبيب الباطنة.', 'A review of 38 studies published 2015–2025 on the bidirectional relationship between chronic periodontitis and glycemic control, consolidating evidence that periodontal therapy improves HbA1c by an effect size comparable to adding a medication — and its practical impact on coordinated care between dentists and physicians.', '/pdfs/sample-cv.pdf', '2026', true);
INSERT INTO research_items (sort_order, title_ar, title_en, abstract_ar, abstract_en, link, year, published)
VALUES (2, 'تقرير حالة: ترميم كسر أمامي بالطبقات المركبة', 'Case Report: Layered Composite Restoration of an Anterior Fracture', 'توثيق مقارن خطوة بخطوة لترميم كسر غير معقّد في سن أمامي بتقنية الطبقات، مع قياس مطابقة اللون بعد 6 أشهر وصور سريرية موثقة — من المتوقع عرضه كملصق علمي في اليوم البحثي للكلية.', 'A step-by-step comparative documentation of an uncomplicated anterior fracture restored with the layering technique, including 6-month shade stability readings and clinical photography — submitted as a poster to the faculty research day.', NULL, '2026', true);

-- 8. Volunteering
INSERT INTO volunteering_items (sort_order, title_ar, title_en, description_ar, description_en, image_src, image_alt_ar, image_alt_en, impact, published)
VALUES (0, 'أسبوع الابتسامة', 'Smile Week', 'حملة توعية في أربع مدارس ابتدائية: عروض تفاعلية عن التنظيف الصحيح، فحص فمي مبدئي، وهدايا فرش ومعاجين أسنان للأطفال — مع رسالة للأهالي عن أول زيارة لطبيب الأسنان.', 'An awareness campaign across four elementary schools: interactive brushing demos, preliminary oral screening, and brush-and-paste gifts for the kids — plus a take-home message to parents about the first dental visit.', '/images/vol-1.webp', 'متطوعون يعلمون أطفالاً الطريقة الصحيحة لتنظيف الأسنان في مدرسة', 'Volunteers teaching children the correct way to brush at a school', '[{"labelAr":"طفل فُحص","labelEn":"children screened","value":320,"suffixAr":"","suffixEn":""},{"labelAr":"حصة توعية","labelEn":"awareness sessions","value":12,"suffixAr":"","suffixEn":""}]'::jsonb, true);
INSERT INTO volunteering_items (sort_order, title_ar, title_en, description_ar, description_en, image_src, image_alt_ar, image_alt_en, impact, published)
VALUES (1, 'فحوصات رمضان الوقائية', 'Ramadan Preventive Checkups', 'خيمة صحية في حيّ المدينة قبل رمضان بأسبوع: فحوصات مجانية وتثقيف عن صحة الفم أثناء الصيام، بالتعاون مع عيادة متنقلة ومتطوعين من الكلية.', 'A neighborhood health tent a week before Ramadan: free screenings and education about oral health while fasting, in partnership with a mobile clinic and faculty volunteers.', '/images/vol-2.webp', 'خيمة صحية مجتمعية للفحوصات الوقائية', 'A community health tent for preventive checkups', '[{"labelAr":"فحص وقائي","labelEn":"preventive checks","value":180,"suffixAr":"","suffixEn":""},{"labelAr":"متطوع شارك","labelEn":"volunteers involved","value":14,"suffixAr":"","suffixEn":""}]'::jsonb, true);
INSERT INTO volunteering_items (sort_order, title_ar, title_en, description_ar, description_en, image_src, image_alt_ar, image_alt_en, impact, published)
VALUES (2, 'إرشاد طلاب السنوات الأولى', 'Junior Students Mentoring', 'جلسات شهرية مفتوحة لطلاب السنوات الأولى: كيف تتغلب على مواد ما قبل السريرية، وتجربتي الأولى مع المرضى — لأن أحداً لم يرشدني حين احتجت، فلأكن أنا من يفعل.', 'Monthly open sessions for first-year students: how to survive preclinical courses, and what my first patient encounters taught me — because nobody mentored me when I needed it, so I choose to be that person.', '/images/vol-3.webp', 'جلسة إرشاد جماعية لطلاب طب الأسنان', 'A group mentoring session for dental students', '[{"labelAr":"طالب استفاد","labelEn":"students reached","value":95,"suffixAr":"","suffixEn":""},{"labelAr":"جلسة","labelEn":"sessions","value":9,"suffixAr":"","suffixEn":""}]'::jsonb, true);

-- 9. Blog Posts
INSERT INTO blog_posts (slug, sort_order, title_ar, title_en, excerpt_ar, excerpt_en, category, date, reading_minutes, cover_src, cover_alt_ar, cover_alt_en, body_ar, body_en, published)
VALUES ('brushing-technique', 0, 'دقيقتان تغيّران كل شيء: الطريقة الصحيحة لتنظيف أسنانك', 'Two Minutes That Change Everything: How to Brush Properly', 'معظمنا ينظف أسنانه كل يوم — لكن 4 من كل 5 يفعلونها بطريقة تترك الترس يسكنها. إليك ما يحدث في الدقيقتين الصحيحتين.', 'Most of us brush every day — but 4 out of 5 do it in a way that leaves plaque living comfortably behind. Here''s what happens in the right two minutes.', '{"ar":"العناية اليومية","en":"Daily care"}', '2026-08-12', 4, '/images/blog-1.webp', 'فرشاة أسنان ومعجون بجانب مغسلة', 'A toothbrush and toothpaste beside a sink', '[{"type":"p","text":"في العيادة التدريبية أبدأ كل جلسة تنظيف بسؤال بسيط: «كيف تنظف أسنانك؟» ثم أستمع. الإجابة الأكثر تكراراً: «فرشاة أفقية سريعة، دقيقة أو أقل، وضغط قوي» — أي بالضبط الوصفة التي تجعل الترس يفرّ من الشعيرات ويسكن اللثة."},{"type":"h2","text":"المشكلة ليست في الاجتهاد، بل في الاتجاه"},{"type":"p","text":"الترس الجرثومي طبقة رقيقة تلتصق عند خط التقاء السن باللثة — النقطة التي لا تصلها حركة أفقية مهما اجتهدت، بل تدفعها غالباً نحو اللثة فتثيرها. ما تحتاجه هو زاوية 45 درجة: أمل الفرشاة نحو اللثة بحيث تدخل الشعيرات بلطف تحت حافتها، ثم حركات قصيرة مهزوزة موضعية، سنًّاً بعد سن."},{"type":"p","text":"الضغط القوي خطأ شائع ثانٍ: الشعيرات تنثني فتفقد ملامستها للسطح، وتتآكل اللثة مع الوقت وتتراجع كاشفةً جذوراً حساسة. القاعدة: ضغط بوزن عملة صغيرة فقط، وفرشاة ناعمة دائماً."},{"type":"h2","text":"خطة الدقيقتين"},{"type":"ul","items":["قسّم فمك إلى أرباع: أعلى يمين، أعلى يسار، أسفل يمين، أسفل يسار.","امنح كل ربع 30 ثانية — مؤقت الهاتف يحل المشكلة تماماً.","الأسطح الخارجية والداخلية والطاحنة: كل سطح له دوره، والزوايا الداخلية للأنياب هي أكثر ما يُنسى.","نظف لسانك في آخر 10 ثوانٍ؛ نصف رائحة الفم تسكنه.","استبدل الفرشاة كل 3 أشهر أو بعد أي مرض حلق."]},{"type":"p","text":"لاحظ فرقاً في غضون أسبوعين: نزيف أقل عند التنظيف، ونفس أنقى في الصباح. وإن نزفت اللثة في البدايات فلا تتوقف — التنظيف الصحيح هو العلاج، لا السبب."},{"type":"p","text":"هذا المقال تثقيف عام لا يغني عن الفحص الدوري؛ حالتك الخاصة قد تحتاج خطة مختلفة — اسأل طبيبك دائماً."}]'::jsonb, '[{"type":"p","text":"In the teaching clinic I start every hygiene session with one simple question: ''How do you brush?'' Then I listen. The most common answer: ''a quick horizontal scrub, under a minute, with strong pressure'' — which is exactly the recipe that lets plaque dodge the bristles and settle at the gumline."},{"type":"h2","text":"The problem isn''t effort — it''s direction"},{"type":"p","text":"Dental plaque is a thin film that clings where tooth meets gum — the exact spot a horizontal scrub never reaches, and usually just pushes into the gums, irritating them. What works is a 45-degree angle: tilt the brush toward the gums so the bristles slip gently under the gum margin, then short, gentle jiggling strokes, tooth by tooth."},{"type":"p","text":"Pressing hard is the second classic mistake: bristles bend away from the surface, and gums slowly recede, exposing sensitive roots. The rule: the pressure of a small coin at most, and always a soft brush."},{"type":"h2","text":"The two-minute plan"},{"type":"ul","items":["Split your mouth into quarters: upper right, upper left, lower right, lower left.","Give each quarter 30 seconds — your phone timer solves this completely.","Outer, inner, and chewing surfaces all get their turn; the inner corners of the canines are the most forgotten spot.","Brush your tongue for the last 10 seconds; half of breath odor lives there.","Replace your brush every 3 months, or right after any throat illness."]},{"type":"p","text":"Expect a difference within two weeks: less bleeding when you brush and a fresher morning breath. And if your gums bleed a little at first, don''t stop — correct brushing is the treatment, not the cause."},{"type":"p","text":"This article is general education, not a substitute for regular check-ups; your specific situation may need a different plan — always ask your dentist."}]'::jsonb, true)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO blog_posts (slug, sort_order, title_ar, title_en, excerpt_ar, excerpt_en, category, date, reading_minutes, cover_src, cover_alt_ar, cover_alt_en, body_ar, body_en, published)
VALUES ('bleeding-gums', 1, 'لماذا تنزف لثتك عند التنظيف؟ (ولماذا لا يجب تجاهلها؟)', 'Why Do Your Gums Bleed When You Brush? (and Why You Shouldn''t Ignore It)', 'الدم في المغسل ليس «شيئاً طبيعياً» كما يظن كثيرون — إنه أول نداء استغاثة من لثة قابلة للشفاء تماماً إن تعاملت معه مبكراً.', 'Blood in the sink isn''t ''just normal'' as many assume — it''s the first distress call from gums that are completely healable if you act early.', '{"ar":"صحة اللثة","en":"Gum health"}', '2026-07-03', 5, '/images/blog-2.webp', 'طبيب أسنان يفحص لثة مريض بمرآة فحص', 'A dentist examining a patient''s gums with a dental mirror', '[{"type":"p","text":"«دم بسيط عند التنظيف، وينقطع بعد يومين إذا استرحت من الفرشاة» — هذه الجملة أسمعها أسبوعياً في العيادة، وهي أخطر ما في الموضوع: النزيف يقل لأن اللثة الملتهبة تهدأ مؤقتاً عند تركها، بينما يستمر السبب الحقيقي في العمل بصمت."},{"type":"h2","text":"ما الذي يحدث فعلاً؟"},{"type":"p","text":"النزيف في الغالبية الساحقة من الحالات ليس من السن بل من اللثة الملتهبة بالترس الجرثومي المتراكم عند خط اللثة. الجسم يرسل دماً أكثر إلى المنطقة كجزء من التهاب دفاعي، فتتورم الأوعية الدقيقة وتنزف عند أي لمسة. التوقف عن التنظيف يعني هدنة مؤقتة مع تراكم مستمر — والمرحلة التالية اسمها الجيوب وتراجع العظم، وهنا يصبح الطريق أطول بكثير."},{"type":"p","text":"الخبر الجيد: في مرحلة الالتهاب البسيط (قبل الجيوب) يستغرق الشفاء أسبوعين إلى ثلاثة من التنظيف الصحيح فقط — دون أدوية في معظم الحالات."},{"type":"h2","text":"خطة الأسبوعين"},{"type":"ul","items":["استمر بالتنظيف مرتين يومياً بالطريقة الصحيحة (زاوية 45 درجة، ضغط خفيف) — النزيف سيقل يوماً بعد يوم.","أدخل الخيط مرة واحدة يومياً؛ هو الوحيد القادر على تنظيف ما بين الأسنان حيث يبدأ نصف الالتهابات.","فرشاة ناعمة جديدة تبدأ العد من جديد — الشعيرات البالية تخدش ولا تنظف.","إن استمر النزيف بعد 14 يوماً من الالتزام، أو رافق رائحة ثابتة أو انحساراً في اللثة، فهذا موعد وليس اجتهاداً."]},{"type":"p","text":"حالات تستدعي زيارة أسرع: نزيف تلقائي دون تنظيف، أو مصحوب بأدوية مسيّلة للدم أو سكري غير متحكم به أو حمل — كلها تغيّر الخطة وتحتاج تقييماً مهنياً."}]'::jsonb, '[{"type":"p","text":"''A little blood when I brush — it stops after two days if I give the brush a rest.'' I hear this weekly in the clinic, and it''s the most dangerous part: the bleeding eases because irritated gums calm down when left alone, while the real cause keeps working silently."},{"type":"h2","text":"What''s actually happening?"},{"type":"p","text":"In the vast majority of cases the blood comes not from the teeth but from gums inflamed by plaque accumulated at the gumline. The body sends extra blood to the area as part of a defensive inflammation, so the tiny vessels swell and bleed at the slightest touch. Stopping brushing buys a temporary truce while accumulation continues — and the next stage is called pockets and bone loss, a much longer road."},{"type":"p","text":"The good news: at the simple gingivitis stage (before pockets), healing takes two to three weeks of correct brushing alone — no medication in most cases."},{"type":"h2","text":"The two-week plan"},{"type":"ul","items":["Keep brushing twice daily with the correct technique (45-degree angle, light pressure) — the bleeding will ease day by day.","Add floss once a day; it''s the only tool that cleans between teeth, where half of all inflammation begins.","A new soft brush resets the clock — worn bristles scratch instead of clean.","If bleeding persists after 14 consistent days, or comes with persistent odor or gum recession, that''s an appointment, not more effort."]},{"type":"p","text":"Cases that warrant a sooner visit: spontaneous bleeding without brushing, or bleeding alongside blood thinners, uncontrolled diabetes, or pregnancy — all of these change the plan and need professional assessment."}]'::jsonb, true)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO blog_posts (slug, sort_order, title_ar, title_en, excerpt_ar, excerpt_en, category, date, reading_minutes, cover_src, cover_alt_ar, cover_alt_en, body_ar, body_en, published)
VALUES ('tooth-sensitivity', 2, 'حساسية الأسنان: الأسباب السبعة والحلول التي تعمل فعلاً', 'Tooth Sensitivity: Seven Causes and What Actually Helps', 'شربت ماءً بارداً فتئزّ؟ الحساسية رسالة من السن — افهم لغتها قبل أن تشتري المبيّض التالي.', 'Wincing at a cold drink? Sensitivity is your tooth''s message — learn its language before buying the next whitening kit.', '{"ar":"نصائح","en":"Tips"}', '2026-06-18', 6, '/images/blog-3.webp', 'كوب ماء بارد بجانب قطع ثلج', 'A cold glass of water beside ice cubes', '[{"type":"p","text":"الحساسية ليست مرضاً بذاتها بل عرضاً: أنبوبات مجهرية داخل المينا المكشوفة تنقل البرد والحامض مباشرة إلى عصب السن. معرفة السبب هي نصف العلاج — وإليك الأسباب السبعة التي أراها مرتبة بالشيوع."},{"type":"ul","items":["تنظيف قاسٍ وفرشاة خشنة يتركان اللثة منحسرة عن الجذر الحساس.","ترس حمضي من المشروبات الغازية والحامضية والارتجاع المريئي يذيب المينا ببطء.","صرّ الأسنان الليلي يطحن طبقة المينا على الأسطح الطاحنة.","تسوس أو حشوة مكسورة — الحساسية المركزة في سن واحد تحديداً.","فوراً بعد تنظيف مهني أو تبييض: مؤقتة وطبيعية وتنتهي خلال أيام.","لثة منحسرة عمراً أو بعد علاج لثة، فتنكشف جذور بلا مينا أصلاً.","حساسية مستمرة بعد علاج جذور حديث تستدعي مراجعة الطبيب."]},{"type":"h2","text":"ما الذي يعمل فعلاً؟"},{"type":"p","text":"معجون الحساسية (مركبات البوتاسيوم والفلورايد القوي) ليس خرافة — لكنه يحتاج أسبوعين إلى أربعة من الاستخدام المنتظم مرتين يومياً حتى يغلق الأنبوبات، ويفقد أثره عند التوقف. مرّر المعجون بإصبعك على المواضع الحساسة قبل النوم واتركه دون غسل ليلة كاملة؛ هذه الحيلة تضاعف الأثر."},{"type":"p","text":"المينا لا تُشترى من الرف: اشرب المشروبات الحامضية بماصة، وانتظر 30 دقيقة قبل التنظيف بعد أي مشروب حمضي (المينا تليّن مؤقتاً والفرشاة المبكرة تجرفها)، وغالباً ما يكشف النقاش مع طبيبك سبباً بسيطاً — ضغط الفرشاة مثلاً — يوفر عليك شهوراً من المعجون."},{"type":"p","text":"علامة تحذير: ألم يوقظك ليلاً أو يستمر بعد إزالة المؤثر — هذا ليس تعريفاً للحساسية، بل غالباً لبٌّ يحتاج تقييماً فورياً."}]'::jsonb, '[{"type":"p","text":"Sensitivity isn''t a disease of its own but a symptom: microscopic tubules in exposed dentin transmit cold and acid straight to the tooth''s nerve. Knowing the cause is half the cure — here are the seven causes I see, ordered by frequency."},{"type":"ul","items":["Aggressive brushing and hard brushes, leaving gums receded over sensitive root surfaces.","Acid wear from sodas, acidic drinks, and reflux, slowly dissolving enamel.","Nighttime grinding, wearing enamel off the chewing surfaces.","Caries or a fractured filling — sensitivity concentrated in one specific tooth.","Right after professional cleaning or whitening: temporary, normal, and gone within days.","Gums receded with age or after gum treatment, exposing dentin that never had enamel.","Persistent sensitivity after a recent root canal — worth having your dentist re-examine."]},{"type":"h2","text":"What actually works?"},{"type":"p","text":"Sensitivity toothpaste (potassium and stannous fluoride compounds) isn''t a gimmick — but it needs two to four weeks of consistent twice-daily use to plug the tubules, and the effect fades once you stop. Rub a fingertip of it onto the sensitive spots before bed and leave it unwashed overnight; this trick multiplies the effect."},{"type":"p","text":"Enamel isn''t bought off a shelf: drink acidic beverages through a straw, wait 30 minutes before brushing after any acidic drink (enamel is temporarily softened and early brushing sweeps it away), and the conversation with your dentist often reveals a simple cause — brush pressure, for instance — that spares you months of paste."},{"type":"p","text":"A warning sign: pain that wakes you at night or lingers after the trigger is gone — that''s not the definition of sensitivity, it''s most often a pulp that needs urgent assessment."}]'::jsonb, true)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO blog_posts (slug, sort_order, title_ar, title_en, excerpt_ar, excerpt_en, category, date, reading_minutes, cover_src, cover_alt_ar, cover_alt_en, body_ar, body_en, published)
VALUES ('flossing', 3, 'خيط الأسنان: الخطوة التي يتجاهلها معظمنا', 'Flossing: The Step Most of Us Skip', 'الفرشاة تنظف 3 من 5 أسطح في فمك — الخيط هو الوحيد الذي يصل إلى السطحين الباقيين. لماذا نتجنبه؟ وكيف نستطيع جعله عادة؟', 'Your brush cleans 3 of the 5 surfaces in your mouth — floss is the only thing that reaches the remaining two. Why do we skip it, and how do we make it stick?', '{"ar":"العناية اليومية","en":"Daily care"}', '2026-05-22', 3, '/images/blog-4.webp', 'خيط أسنان ملتف حول إصبعين', 'Dental floss wrapped around two fingers', '[{"type":"p","text":"إذا كان فمك شقةً من خمس غرف، فالفرشاة عامل نظافة يدخل ثلاثاً منها فقط. السطحان الباقيان — ما بين كل سنّين متجاورين — هما حيّ الترس الراقي: لا هواء، لا لعاب، ولا شعيرات فرشاة. الخيط هو الزائر الوحيد المسموح له بالدخول."},{"type":"h2","text":"لماذا نتجنله إذاً؟"},{"type":"ul","items":["أول تجربة كانت مؤلمة (لثة ملتهبة تنزف) فحكمنا على العادة من أول يوم.","لا أحد أرانا كيف: الخيط مهارة يدوية تحتاج تمريناً كأي مهارة.","نربطه بمناسبات خاصة «قبل موعد الطبيب» بدل ربطه بالماء والفرشاة."]},{"type":"p","text":"القاعدة العملية: ابدأ بثلاثة أسنان فقط كل ليلة — الأنياب السفلية مثلاً — لمدة أسبوع. الألم والنزيف يتراجعان خلال أيام لأن الالتهاب نفسه يبدأ بالانسحاب. ثم وسّع تدريجياً حتى تشمل الجولة كاملة. ربطه بعادة قائمة (بعد فرشاة المساء مباشرة) يجعله تلقائياً."},{"type":"p","text":"خيطك يخبرك عن صحة فمك أيضاً: رائحة على الخيط بعد تنظيف منطقة معينة تعني أن الترس ما يزال يعيش هناك — مؤشر تقدمك الخاص."}]'::jsonb, '[{"type":"p","text":"If your mouth were a five-room apartment, the brush would be a cleaner who only enters three rooms. The remaining two surfaces — between every pair of adjacent teeth — are plaque''s luxury district: no airflow, no saliva wash, no bristles. Floss is the only visitor allowed in."},{"type":"h2","text":"So why do we skip it?"},{"type":"ul","items":["The first experience hurt (inflamed gums bleeding), so we judged the habit by day one.","Nobody showed us how: flossing is a manual skill that needs practice like any skill.","We tie it to special occasions (''before the dentist appointment'') instead of pairing it with water and brush."]},{"type":"p","text":"The practical rule: start with just three teeth each night — the lower canines, say — for one week. Pain and bleeding recede within days because the inflammation itself starts withdrawing. Then expand gradually until the full tour. Pairing it with an existing habit (right after the evening brush) makes it automatic."},{"type":"p","text":"Your floss also reports on your oral health: an odor on the floss after cleaning a specific area means plaque still lives there — your own progress dashboard."}]'::jsonb, true)
ON CONFLICT (slug) DO NOTHING;

-- 10. FAQ
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (0, 'كم مرة أزور طبيب الأسنان فعلاً؟', 'How often do I really need to see a dentist?', 'القاعدة العامة كل 6 أشهر للفحص والتنظيف، لكنها ليست رقماً مقدساً: من لديه لثة ملتهبة أو تقويم أو تاريخ تسوس نشط قد يحتاج كل 3-4 أشهر، ومن حالته مستقرة قد تكفيه زيارة سنوية. القرار يُبنى على فحص، لا على تقويم عام.', 'The general rule is every 6 months for a check-up and cleaning, but it isn''t sacred: anyone with gum inflammation, braces, or an active caries history may need every 3–4 months, while a stable mouth might do fine with an annual visit. The decision is built on an exam, not a calendar.', true);
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (1, 'هل تبييض الأسنان آمن؟ يُضعف المينا؟', 'Is teeth whitening safe? Does it weaken enamel?', 'التبييض الاحترافي تحت إشراف طبيب آمن ولا يُذيب المينا — قد يسبب حساسية مؤقتة تُدار بمعاجين الفلورايد. أما الخطرة الحقيقية ففي المنتجات العشوائية عالية التركيز وبلا فحص مسبق: حشوات قديمة أو تسوس كامن يتحول بعدها إلى ألم حقيقي. الفحص أولاً، ثم التبييض.', 'Professional whitening supervised by a dentist is safe and doesn''t dissolve enamel — it may cause temporary sensitivity managed with fluoride pastes. The real danger is random high-concentration products used without a prior exam: old fillings or hidden caries can turn into real pain afterward. Exam first, whiten second.', true);
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (2, 'الفرشاة الكهربائية أفضل من العادية؟', 'Are electric brushes better than manual ones?', 'لمن يتقن التنظيف اليدوي، الفرق صغير. لكن الدراسات تُظهر أن الفرشاة الكهربائية ذات رأس دوّار تعطي تنظيفاً أفضل لمن يندفع بالضغط القوي أو يحرك الفرشاة بعشوائية، ولأصحاب التقويم والمهارات اليدوية المحدودة. التقنية الأهم تبقى: زاوية 45 درجة ووقت كافٍ.', 'For someone with perfect manual technique, the difference is small. But studies show rotating electric brushes clean better for those who press hard or brush erratically, and for people with braces or limited manual dexterity. The technique that matters most stays the same: a 45-degree angle and enough time.', true);
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (3, 'متى أول زيارة لطفلي لطبيب الأسنان؟', 'When should my child first see a dentist?', 'مع بزوغ أول سن — أي حوالي عمر السنة — أو بعدها بستة أشهر على الأكثر. الزيارة الأولى ليست عن العلاج بل عن التعوّد: طبيب ودود، كرسي «سحري»، وتقييم سريع لعادة مصّ الإصبع أو اللسان، وأهم شيء: أن تخرجا قبل أن يملّ الطفل.', 'When the first tooth erupts — around age one — or within six months after at the latest. The first visit isn''t about treatment but about getting comfortable: a friendly dentist, a ''magic'' chair, a quick look at thumb-sucking habits, and most importantly, leaving before the child gets bored.', true);
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (4, 'هل علاج الجذور مؤلم فعلاً كما يشاع؟', 'Is a root canal as painful as its reputation?', 'الشهرة قديمة من عصر قبل التخدير الحديث. اليوم: تخدير موضعي فعّال يجعل الجلسة أقرب لحشوة عادية، والألم الذي يُذكر تاريخياً هو ألم اللب الملتهب قبل العلاج — أي أن العلاج نفسه هو الذي يوقف الألم. مريضي بعد أول جلسة: «هذا كل شيء؟».', 'The reputation dates from an era before modern anesthesia. Today: effective local anesthesia makes the session closer to a normal filling, and the pain people remember historically is the inflamed pulp hurting *before* treatment — meaning the treatment itself is what stops the pain. My patients after a first session: ''That''s it?''', true);
INSERT INTO faq_items (sort_order, q_ar, q_en, a_ar, a_en, published)
VALUES (5, 'نزيف اللثة يجب أن أتوقف عن التنظيف حين يحدث؟', 'Bleeding gums mean I should stop brushing?', 'العكس تماماً — هو نداء للاستمرار بشكل صحيح. النزيف علامة التهاب من الترس المتراكم، والتنظيف اللطيف بزاوية 45 درجة مرتين يومياً هو العلاج الأولي. إن استمر النزيف أكثر من أسبوعين رغم الالتزام، فالزيارة التالية تصبح ضرورة.', 'Exactly the opposite — it''s a call to continue, correctly. Bleeding signals inflammation from accumulated plaque, and gentle twice-daily brushing at a 45-degree angle is the first-line treatment. If bleeding persists beyond two weeks despite the effort, the next visit becomes a necessity.', true);

