-- 12. Testimonials
INSERT INTO testimonials (sort_order, quote_ar, quote_en, author_ar, author_en, role_ar, role_en, initials, rating, published)
VALUES (0, 'جنية الأسنان نموذج متميز يسأل «لماذا» قبل «كيف». يدها مطمئنة وشرحها للمرضى يبعث على الراحة والأمان.', 'Tooth Fairy''s World embodies the rare standard of asking ''why'' before ''how''. Steady hands, gentle care, and patient explanations that build real confidence.', NULL, NULL, 'مشرف سريري — قسم الترميمات', 'Clinical supervisor — Restorative Dept.', 'AK', undefined, true);
INSERT INTO testimonials (sort_order, quote_ar, quote_en, author_ar, author_en, role_ar, role_en, initials, rating, published)
VALUES (1, 'حضورها في المحاضرات لا يكتفي بالتسجيل؛ أسئلتها تفتح النقاش دائماً. أتوقع لها بحثاً جيداً في مشروع التخرج.', 'In lectures she doesn''t just take notes; her questions always open the discussion. I expect strong research from her graduation project.', NULL, NULL, 'أستاذة مساعدة — علاج الجذور', 'Associate professor — Endodontics', 'LM', undefined, true);
INSERT INTO testimonials (sort_order, quote_ar, quote_en, author_ar, author_en, role_ar, role_en, initials, rating, published)
VALUES (2, 'في الليلات التي سبقت امتحان علاج الجذور كانت ملخصاتها تنتقل بين الطلاب أكثر من الكتاب نفسه.', 'On the nights before our endodontics exam, her summaries circulated among students more than the textbook itself.', NULL, NULL, 'زميل دفعة', 'Classmate', 'HA', undefined, true);
INSERT INTO testimonials (sort_order, quote_ar, quote_en, author_ar, author_en, role_ar, role_en, initials, rating, published)
VALUES (3, 'جلساتها الإرشادية اختصرت لي شهراً من التخبط في السنة الثانية. تشرح كأنها تجلس معك في السن ذاته.', 'Her mentoring sessions saved me a month of floundering in second year. She explains as if she''s sitting in that same year with you.', NULL, NULL, 'طالبة سنة ثالثة', 'Third-year student', 'NS', undefined, true);
INSERT INTO testimonials (sort_order, quote_ar, quote_en, author_ar, author_en, role_ar, role_en, initials, rating, published)
VALUES (4, 'في حملة أسبوع الابتسامة أدارت 60 طفلاً في صباح واحد دون أن تفقد ابتسامتها — عادت ليكتب تقريراً كاملاً في المساء.', 'During Smile Week she managed 60 children in a single morning without losing her smile — then went home and wrote the full report that evening.', NULL, NULL, 'منسقة حملات التوعية', 'Awareness campaign coordinator', 'RF', undefined, true);

